import { getGlobalReports, getDaftarRuangan } from "@/services/ppi";
import { getLoggedUserProfile } from "@/services/auth";
import { redirect } from "next/navigation";
import { Files, Search, Calendar, Filter } from "lucide-react";
import TabelRekapPPI from "./TabelRekapPPI";

export const dynamic = "force-dynamic";

/**
 * Halaman Rekap Laporan Global PPI - RS ARUN
 * Menggunakan Next.js 16 Async searchParams
 */
export default async function RekapLaporanPPIPage({
  searchParams,
}: {
  searchParams: Promise<{ ruangan?: string; start?: string; end?: string }>;
}) {
  // 1. Verifikasi Keamanan & Role
  const profile = await getLoggedUserProfile();
  if (!profile || profile.role !== "PPI") {
    redirect("/login");
  }

  // 2. Await searchParams (Wajib di Next.js 16)
  const params = await searchParams;
  const filterRuangan = params.ruangan || "all";
  const filterStart = params.start || "";
  const filterEnd = params.end || "";

  // 3. Ambil Data secara Paralel untuk efisiensi
  const [daftarRuangan, reports] = await Promise.all([
    getDaftarRuangan(),
    getGlobalReports({
      ruangan_id: filterRuangan,
      startDate: filterStart,
      endDate: filterEnd,
    })
  ]);

  return (
    <div className="space-y-6">
      {/* HEADER SECTION */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
        <div className="flex items-center gap-5">
          <div className="p-4 bg-blue-600 text-white rounded-3xl shadow-xl shadow-blue-100">
            <Files size={28} />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Rekap Laporan Global</h1>
            <p className="text-sm font-semibold text-slate-500 uppercase tracking-[0.15em] mt-1">
              Arsip Data Surveilans • Seluruh Unit RS Arun
            </p>
          </div>
        </div>
      </div>

      {/* FILTER PANEL */}
      <div className="bg-white p-2 rounded-[2.5rem] border border-slate-100 shadow-sm">
        <form className="grid grid-cols-1 md:grid-cols-4 gap-2 p-2">
          {/* Filter Ruangan */}
          <div className="relative group">
            <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-600 transition-colors">
              <Filter size={18} />
            </div>
            <select 
              name="ruangan" 
              defaultValue={filterRuangan}
              className="w-full pl-12 pr-4 py-4 bg-slate-50 border-none rounded-[1.5rem] text-sm font-bold text-slate-700 outline-none focus:ring-2 focus:ring-blue-500/20 transition-all appearance-none"
            >
              <option value="all">Semua Ruangan</option>
              {daftarRuangan.map((r) => (
                <option key={r.id} value={r.id}>{r.nama_ruangan}</option>
              ))}
            </select>
          </div>

          {/* Tanggal Mulai */}
          <div className="relative group">
            <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
              <Calendar size={18} />
            </div>
            <input 
              type="date" 
              name="start"
              defaultValue={filterStart}
              className="w-full pl-12 pr-4 py-4 bg-slate-50 border-none rounded-[1.5rem] text-sm font-bold text-slate-700 outline-none focus:ring-2 focus:ring-blue-500/20 transition-all"
            />
          </div>

          {/* Tanggal Akhir */}
          <div className="relative group">
            <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
              <Calendar size={18} />
            </div>
            <input 
              type="date" 
              name="end"
              defaultValue={filterEnd}
              className="w-full pl-12 pr-4 py-4 bg-slate-50 border-none rounded-[1.5rem] text-sm font-bold text-slate-700 outline-none focus:ring-2 focus:ring-blue-500/20 transition-all"
            />
          </div>

          {/* Tombol Cari */}
          <button 
            type="submit"
            className="bg-slate-900 text-white py-4 rounded-[1.5rem] font-bold text-sm flex items-center justify-center gap-2 hover:bg-slate-800 transition-all shadow-lg active:scale-[0.98]"
          >
            <Search size={18} /> Tampilkan Laporan
          </button>
        </form>
      </div>

      {/* TABLE SECTION */}
      {/* Jaminan reports || [] memastikan data tidak undefined 
        saat dikirim ke Client Component 
      */}
      <TabelRekapPPI data={reports || []} />

      {/* FOOTER INFO */}
      <div className="bg-slate-50 p-6 rounded-[2rem] border border-dashed border-slate-200">
        <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest text-center leading-relaxed">
          Catatan: Rekapitulasi ini hanya menampilkan data yang telah melalui proses verifikasi oleh Petugas PPI.<br/>
          Gunakan fitur filter untuk spesifikasi laporan per unit atau periode tertentu.
        </p>
      </div>
    </div>
  );
}